"""Text formats, interval indexing, and shared output conventions."""
import sys, os, gzip, math, re, struct
from collections import defaultdict, OrderedDict

class ToolError(Exception):
    def __init__(self, message, code=1): self.message, self.code = message, code

def fail(message, code=1): raise ToolError(message, code)
def err(message): sys.stderr.write(message)
def emit(*fields): sys.stdout.write('\t'.join(map(str, fields))+'\n')
def line(fields): return '\t'.join(map(str,fields))
def num(x, prec=6):
    if isinstance(x, int): return str(x)
    if math.isnan(x): return 'nan'
    if math.isinf(x): return '-inf' if x < 0 else 'inf'
    return format(x, '.%dg' % prec)
def f32(x):
    try: return struct.unpack('f',struct.pack('f',x))[0]
    except OverflowError: return math.copysign(float('inf'),x)
def fixed(x, p=7, single=False):
    if single: x=f32(x)
    return format(x,'.%df'%p)
def integer(s): return bool(re.fullmatch(r'[+-]?\d+',s))
def number(s, default=0):
    try: return float(s)
    except (ValueError,TypeError): return default

def read_bytes(path, old=False):
    path=str(path)
    try:
        data = sys.stdin.buffer.read() if path in ('-', 'stdin', '/dev/stdin') else open(path,'rb').read()
    except (OSError,ValueError) as e:
        if old: fail(f'Error: The requested file ({path}) could not be opened. Error message: (No such file or directory). Exiting!\n')
        fail(f'Error: Unable to open file {path}. Exiting.\n')
    if data[:2]==b'\x1f\x8b':
        try: data=gzip.decompress(data)
        except Exception: fail(f'Error: Unable to read file {path}. Exiting.\n')
    return data

def read_text(path, old=False): return read_bytes(path,old).decode('utf8',errors='replace')

class Record:
    __slots__=('fields','chrom','start','end','orig_start','orig_end','zero','kind','strand','name','score','index','fileid','file','bam')
    def __init__(self, fields, kind='bed', index=0, file='', fileid=0):
        self.fields=list(fields); self.kind=kind; self.index=index; self.file=file; self.fileid=fileid; self.bam=None
        self.chrom=fields[0]; self.strand='.'; self.name=''; self.score='.'
        if kind=='gff':
            s,e=int(fields[3])-1,int(fields[4]); self.strand=fields[6]; self.name=fields[2]; self.score=fields[5]
        elif kind=='vcf':
            s=int(fields[1])-1; e=s+len(fields[3]); self.name=fields[2]; self.score=fields[5]
            if len(fields)>7:
                m=re.search(r'(?:^|;)END=(\d+)(?:;|$)',fields[7])
                if m: e=int(m.group(1))
        else:
            s,e=int(fields[1]),int(fields[2])
            if len(fields)>3: self.name=fields[3]
            if len(fields)>4: self.score=fields[4]
            if len(fields)>5: self.strand=fields[5]
        self.orig_start=s; self.orig_end=e; self.zero=(s==e)
        self.start=s-1 if self.zero else s; self.end=e+1 if self.zero else e
    def out(self, start=None, end=None, chrom=None):
        f=list(self.fields)
        if chrom is not None: f[0]=chrom
        s=self.orig_start if start is None else int(start)
        e=self.orig_end if end is None else int(end)
        if self.kind=='gff': f[3],f[4]=str(s+1),str(e)
        elif self.kind=='vcf': pass
        else: f[1],f[2]=str(s),str(e)
        return f
    def blocks(self, split=True):
        if not split: return [(self.start,self.end)]
        if self.kind=='bed' and len(self.fields)>=12:
            try:
                n=int(self.fields[9]); sizes=[int(x) for x in self.fields[10].rstrip(',').split(',')]; offsets=[int(x) for x in self.fields[11].rstrip(',').split(',')]
                if n!=len(sizes) or n!=len(offsets):
                    fail('Error: found wrong block counts while splitting entry.\n')
                return [(self.start+x,self.start+x+y) for x,y in zip(offsets,sizes)]
            except ValueError: fail('Error: found wrong block counts while splitting entry.\n')
        return [(self.start,self.end)]
    def __str__(self): return line(self.out())

class BedFile:
    def __init__(self, path='stdin', old=False, fileid=0, raw=False):
        self.path=path; self.header=[]; self.records=[]; self.nfields=0; self.kind='bed'; self.old=old
        data=read_bytes(path,old)
        if data.startswith(b'BAM\x01'):
            from bam import decode_bam
            decode_bam(self,data,fileid)
            return
        text=data.decode('utf8',errors='replace')
        vcf=False; begun=False
        for lineno,ln in enumerate(text.splitlines(),1):
            if not ln.strip(): continue
            if ln.startswith(('#','track','browser')):
                if not begun: self.header.append(ln)
                if ln.startswith('##fileformat=VCF') or ln.startswith('#CHROM'): vcf=True
                continue
            fields=ln.split('\t'); begun=True
            if raw:
                self.records.append(fields); self.nfields=max(self.nfields,len(fields)); continue
            if self.nfields and len(fields)!=self.nfields:
                if old: fail(f'Differing number of BED fields encountered at line: {lineno}.  Exiting...\n')
                fail('Error: Type checker found wrong number of fields while tokenizing data line.\nPerhaps you have extra TAB at the end of your line? Check with "cat -t"\n')
            if not self.nfields:
                kind=None
                if len(fields)>=3 and integer(fields[1]) and integer(fields[2]): kind='bed'
                elif len(fields)>=8 and integer(fields[3]) and integer(fields[4]): kind='gff'
                elif len(fields)>=8 and integer(fields[1]): kind='vcf'
                if vcf and len(fields)>=8 and integer(fields[1]): kind='vcf'
                if kind=='bed' and int(fields[1])>int(fields[2]) and not old: kind=None
                if kind is None:
                    if old:
                        if len(fields)<3: fail(f'It looks as though you have less than 3 columns at line {lineno} in file {path}.  Are you sure your files are tab-delimited?\n')
                        fail(f'Unexpected file format.  Please use tab-delimited BED, GFF, or VCF. Perhaps you have non-integer starts or ends at line {lineno}?\n')
                    fail(f'Error: unable to open file or unable to determine types for file {path}\n\n- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n- Also ensure that your file has integer chromosome coordinates in the \n  expected columns (e.g., cols 2 and 3 for BED).\n')
                self.kind=kind; self.nfields=len(fields)
            try: rec=Record(fields,self.kind,len(self.records),path,fileid)
            except (ValueError,IndexError): fail(f'Error: Invalid record in file {path}. Record is \n{ln}\n')
            if rec.orig_start<0 or rec.orig_end<rec.orig_start:
                if old:
                    if rec.orig_start<0: fail(f'Unexpected file format.  Please use tab-delimited BED, GFF, or VCF. Perhaps you have non-integer starts or ends at line {lineno}?\n')
                    fail(f'Error: malformed BED entry at line {lineno}. Start was greater than end. Exiting.\n')
                fail(f'Error: Invalid record in file {path}. Record is \n{ln}\n')
            self.records.append(rec)
        if not self.nfields: self.nfields=3
    def print_header(self):
        if self.header: sys.stdout.write('\n'.join(self.header)+'\n')
    def null(self, nfields=None):
        n=nfields or self.nfields
        if self.kind=='gff': return ['.','.','.','-1','-1']+['.']*(n-5)
        if self.kind=='vcf': return ['.','-1']+['.']*(n-2)
        return (['.','-1','-1','.','-1','.']+['.']*max(0,n-6))[:n]
    def check_sorted(self, genome=None):
        prev=None; seen=set(); order={c:i for i,c in enumerate(genome or {})}
        for r in self.records:
            bad=False
            if prev:
                if r.chrom==prev.chrom: bad=r.start<prev.start
                else:
                    bad=r.chrom in seen
                    seen.add(prev.chrom)
                    if genome and r.chrom in order and prev.chrom in order and order[r.chrom]<order[prev.chrom]: bad=True
            if genome and r.chrom not in order:
                fail(f'Error: requested chromosome {r.chrom} does not exist in the genome file {getattr(genome,"path","")}. Exiting.\n')
            if bad:
                if genome: fail(f'Error: Sorted input specified, but the file {self.path} has the following record with a different sort order than the genomeFile {genome.path}\n{r}\n')
                fail(f'Error: Sorted input specified, but the file {self.path} has the following out of order record\n{r}\n')
            prev=r

class Genome(OrderedDict):
    def __init__(self,path,old=False):
        super().__init__(); self.path=path
        try: text=read_text(path,old)
        except ToolError:
            fail(f'Error: The requested genome file ({path}) could not be opened. Exiting!\n')
        for ln in text.splitlines():
            if not ln.strip() or ln.startswith('#'): continue
            f=ln.split()
            if len(f)<2:
                fail(f'Error: The genome file {path} has no valid entries (are you sure it is a 2-column bedtools genome file). Exiting.\n')
            try: n=int(f[1])
            except ValueError: n=0
            self[f[0]]=n
        if not self: fail(f'Error: The genome file {path} has no valid entries (are you sure it is a 2-column bedtools genome file). Exiting.\n')

# The overlap index is a hierarchy of power-of-eight coordinate bins.
class IntervalIndex:
    shifts=(14,17,20,23,26,29,32,35,38,41,44,47,50,53,56,59,62)
    def __init__(self,records):
        self.data=defaultdict(lambda:defaultdict(lambda:defaultdict(list)))
        for r in records:
            s,e=max(0,r.start),max(0,r.end-1)
            lev=next((k for k,shift in enumerate(self.shifts) if s>>shift==e>>shift),len(self.shifts)-1)
            self.data[r.chrom][lev][s>>self.shifts[lev]].append(r)
    def query(self,chrom,s,e,ordered=False):
        result=[]
        for lev,bins in sorted(self.data.get(chrom,{}).items()):
            shift=self.shifts[lev]; lo=max(0,s)>>shift; hi=max(0,e-1)>>shift
            keys=range(lo,hi+1) if hi-lo < len(bins)*2 else sorted(k for k in bins if lo<=k<=hi)
            for b in keys:
                for r in bins.get(b,[]):
                    if s<r.end and e>r.start: result.append(r)
        if ordered: result.sort(key=lambda r:(r.chrom,r.start,r.end,r.fileid,r.index))
        return result

def same_strand(a,b,opt):
    sm=opt.get('s',False) or opt.get('sm',False); opp=opt.get('S',False) or opt.get('Sm',False)
    if sm or opp:
        if a.strand not in ('+','-') or b.strand not in ('+','-'): return False
        if sm and a.strand!=b.strand: return False
        if opp and a.strand==b.strand: return False
    return True

def overlap_parts(a,b,split=False):
    return [(max(x,s),min(y,e)) for x,y in a.blocks(split) for s,e in b.blocks(split) if x<e and y>s]

def overlap(a,b,opt):
    if a.chrom!=b.chrom or not same_strand(a,b,opt): return None
    s,e=max(a.start,b.start),min(a.end,b.end)
    if e<=s: return None
    split=opt.get('split',False)
    parts=overlap_parts(a,b,split) if split else [(s,e)]
    amount=sum(e-s for s,e in parts)
    if amount<=0: return None
    la=sum(y-x for x,y in a.blocks(split)); lb=sum(y-x for x,y in b.blocks(split))
    fa=f32(number(opt.get('f',1e-9))); fb=fa if opt.get('r') else f32(number(opt.get('F',1e-9)))
    pa=f32(amount/max(la,1)) >= fa; pb=f32(amount/max(lb,1)) >= fb
    if (pa or pb) if opt.get('e') else (pa and pb): return amount
    return None

def combine(intervals, distance=0):
    out=[]
    for s,e in sorted(intervals):
        if out and s<=out[-1][1]+distance: out[-1]=(out[-1][0],max(e,out[-1][1]))
        else: out.append((s,e))
    return out

def spans(intervals,start=None,end=None):
    changes=defaultdict(int)
    if start is not None: changes[start]+=0
    if end is not None: changes[end]+=0
    for s,e in intervals:
        if start is not None: s=max(s,start)
        if end is not None: e=min(e,end)
        if e>s: changes[s]+=1; changes[e]-=1
    prev=None; depth=0; result=[]
    for x,d in sorted(changes.items()):
        if prev is not None and x>prev:
            if result and result[-1][1]==prev and result[-1][2]==depth: result[-1]=(result[-1][0],x,depth)
            else: result.append((prev,x,depth))
        depth+=d; prev=x
    return result
