        for i in range(1,312): self.mt.append((6364136223846793005*(self.mt[-1]^(self.mt[-1]>>62))+i)&self.MASK)
        self.index=312
    def next(self):
        if self.index>=312:
            for i in range(312):
                x=(self.mt[i]&0xFFFFFFFF80000000)|(self.mt[(i+1)%312]&0x7FFFFFFF)
                self.mt[i]=self.mt[(i+156)%312]^(x>>1)^ (0xB5026F5AA96619E9 if x&1 else 0)
            self.index=0
        x=self.mt[self.index]; self.index+=1
        x^=(x>>29)&0x5555555555555555
        x^=(x<<17)&0x71D67FFFEDA60000
        x^=(x<<37)&0xFFF7EEE000000000
        x^=x>>43
