"""A small, self-contained SAM/BAM and BGZF reader and writer."""
import struct,zlib,re,sys
from collections import OrderedDict,defaultdict
from core import *

CIGAR='MIDNSHP=XB'; SEQ='=ACMGRSVTWYHKDBN'

def bgzf(data):
    out=[]
    for pos in range(0,len(data),65280):
        block=data[pos:pos+65280]; co=zlib.compressobj(6,zlib.DEFLATED,-15); comp=co.compress(block)+co.flush()
        out.append(b'\x1f\x8b\x08\x04\0\0\0\0\0\xff\x06\0BC\x02\0'+struct.pack('<H',len(comp)+25)+comp+struct.pack('<II',zlib.crc32(block)&0xffffffff,len(block)))
    return b''.join(out)
EOF_BLOCK=bytes.fromhex('1f8b08040000000000ff0600424302001b0003000000000000000000')

def regbin(s,e):
    e-=1
    for shift,offset in [(14,4681),(17,585),(20,73),(23,9),(26,1)]:
        if s>>shift==e>>shift: return offset+(s>>shift)
    return 0

def make_header(genome,path,paired=False):
    h='@HD\tVN:1.0\tSO:unsorted\n@PG\tID:BEDTools_'+('bedpeToBam' if paired else 'bedToBam')+'\tVN:V9560abc\n'
    for c,n in genome.items(): h+=f'@SQ\tSN:{c}\tAS:{path}\tLN:{n}\n'
    h=h.encode(); raw=b'BAM\x01'+struct.pack('<i',len(h))+h+struct.pack('<i',len(genome))
    for c,n in genome.items():
        c=c.encode()+b'\0'; raw+=struct.pack('<i',len(c))+c+struct.pack('<i',n)
    return raw

def pack_alignment(name,rid,pos,cigar,flag=0,mapq=255,nextid=-1,nextpos=-1,tlen=0,seq='',qual='',tags=b''):
    qn=name.encode()+b'\0'; nseq=len(seq); end=pos+sum(n for n,c in cigar if c in 'MDN=X')
    data=struct.pack('<iiIIiiii',rid,pos,(regbin(pos,end)<<16)|((mapq&255)<<8)|len(qn),(flag<<16)|len(cigar),nseq,nextid,nextpos,tlen)+qn
    data+=b''.join(struct.pack('<I',(n<<4)|CIGAR.index(c)) for n,c in cigar)
    seq=seq.upper()
    for i in range(0,len(seq),2):
        a=SEQ.find(seq[i]); b=SEQ.find(seq[i+1]) if i+1<len(seq) else 0
        data+=bytes([((max(a,0)<<4)|max(b,0))])
    data+=(bytes(ord(c)-33 for c in qual) if qual and qual!='*' else bytes([255])*nseq)+tags
    return struct.pack('<i',len(data))+data

def output_bam(bf,records):
    header=getattr(bf,'bam_header',None)
    if header is None: return
    sys.stdout.flush(); sys.stdout.buffer.write(bgzf(header)+bgzf(b''.join(r.bam['raw'] for r in records))+EOF_BLOCK)

def cigar_blocks(pos,cigar,splitD=False):
    s=pos; end=pos; out=[]
    for n,op in cigar:
        if op=='N' or (splitD and op=='D'):
            if end>s: out.append((s,end))
            end+=n; s=end
        elif op in 'MD=X': end+=n
    if end>s: out.append((s,end))
    return out or [(pos,end)]

def tags_decode(data):
    out={}; p=0
