"""Unstable comparison sorting used for command-line ordering conventions."""
import math

def interval_sort(values,key=lambda x:x,reverse=False):
    a=[(key(v),v) for v in values]
    def less(x,y): return x[0]>y[0] if reverse else x[0]<y[0]
    def partition(lo,hi):
        x,y,z=lo+1,(lo+hi)//2,hi-1
        if less(a[x],a[y]):
            pivot=y if less(a[y],a[z]) else z if less(a[x],a[z]) else x
        else:
            pivot=x if less(a[x],a[z]) else z if less(a[y],a[z]) else y
        a[lo],a[pivot]=a[pivot],a[lo]
        i,j=lo+1,hi
        while True:
            while less(a[i],a[lo]): i+=1
            j-=1
            while less(a[lo],a[j]): j-=1
            if i>=j: return i
            a[i],a[j]=a[j],a[i]; i+=1
    def divide(lo,hi,depth):
        while hi-lo>16:
            if depth<=0:
                a[lo:hi]=sorted(a[lo:hi],key=lambda x:x[0],reverse=reverse); return
            depth-=1; cut=partition(lo,hi)
            divide(cut,hi,depth); hi=cut
    if a:
        divide(0,len(a),2*int(math.log2(len(a))))
        for i in range(1,len(a)):
            temp=a[i]; j=i
            while j>0 and less(temp,a[j-1]): a[j]=a[j-1]; j-=1
            a[j]=temp
    return [v for k,v in a]
